from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PointTypeStatus(SchemaObject):
    name = SchemaField(name='name')
    value = SchemaField(name='value')

    def __init__(self, name, value):
        self.name = name
        self.value = value

        super(PointTypeStatus, self).__init__()


class CRLInformation(SchemaObject):
    config_dn = SchemaField(name='config_dn', optional=True)
    distribution_point_uri = SchemaField(name='distribution_point_uri', optional=True)
    distribution_point_type = SchemaField(name='distribution_point_type', klass=PointTypeStatus, optional=True)
    download_status = SchemaField(name='download_status', klass=PointTypeStatus, optional=True)
    issuer = SchemaField(name='issuer', optional=True)
    next_update = SchemaField(name='next_update', optional=True)
    num_of_rev_cert = SchemaField(name='num_of_rev_cert', optional=True)
    this_update = SchemaField(name='this_update', optional=True)
    failure_reason = SchemaField(name='update_failure_reason', optional=True)
    crlinfo_r_id = SchemaField(name='crlinfo_r_id', optional=True)

    def __init__(self, config_dn, distribution_point_uri, distribution_point_type, download_status,
                 issuer, next_update, num_of_rev_cert, this_update, failure_reason, crlinfo_r_id):
        self.config_dn = config_dn
        self.distribution_point_uri = distribution_point_uri
        self.distribution_point_type = distribution_point_type
        self.download_status = download_status
        self.issuer = issuer
        self.next_update = next_update
        self.num_of_rev_cert = num_of_rev_cert
        self.this_update = this_update
        self.failure_reason = failure_reason
        self.crlinfo_r_id = crlinfo_r_id

        super(CRLInformation, self).__init__()


class CRLInformations(SchemaObject):
    total = SchemaField(name="total", optional=True)
    update_enabled = SchemaField(name="update_enabled", optional=True)
    crlinfo_list = SchemaField(name="list", klass=CRLInformation, many=True)

    def __init__(self, total, update_enabled, crlinfo_list):
        self.total = total
        self.update_enabled = update_enabled
        self.crlinfo_list = crlinfo_list

        super(CRLInformations, self).__init__()
